  id String @id @db.Uuid

  /// Belonged guest's {@link hrm_platform_guests.id}.
  hrm_platform_guest_id String @db.Uuid

  /// IP address of the guest during session creation for security monitoring.
  ip String

  /// The URL where the guest initiated the session.
  href String @db.VarChar(80000)

  /// The referrer URL that led the guest to the current page.
  referrer String? @db.VarChar(80000)

  /// Timestamp when the guest session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest session expires. Used for session lifecycle
  /// management and security.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  guest hrm_platform_guests @relation(fields: [hrm_platform_guest_id], references: [id], onDelete: Cascade)

