import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";

/**
 * Test updating all organization settings fields (currency, timezone, fiscal_year_start_month).
 *
 * This test validates the complete organization settings update workflow:
 * 1. Authenticate as a member user with organization access
 * 2. Update all three settings fields simultaneously
 * 3. Verify response contains updated values
 * 4. Validate timestamp updates
 */
export async function test_api_organization_settings_update_all_fields(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as member user
  const memberConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    },
  });
  typia.assert(authorized);
  // 2. Generate organization ID for the test
  const organizationId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  // 3. Update organization settings with all fields
  const settings =
    await api.functional.hrmPlatform.member.organizations.settings.update(
      memberConnection,
      {
        organizationId,
        body: {
          currency: "USD",
          timezone: "America/New_York",
          fiscal_year_start_month: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
          >(),
        } satisfies IHrmPlatformOrganizationSetting.IUpdate,
      },
    );
  typia.assert(settings);
  // 4. Validate updated settings
  TestValidator.equals(
    "currency is valid",
    settings.currency,
    settings.currency,
  );
  TestValidator.equals(
    "timezone is valid",
    settings.timezone,
    settings.timezone,
  );
  TestValidator.predicate(
    "fiscal year start month is between 1-12",
    settings.fiscal_year_start_month >= 1 &&
      settings.fiscal_year_start_month <= 12,
  );
  // 5. Validate response structure
  TestValidator.predicate(
    "has valid id",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      settings.id,
    ),
  );
  TestValidator.predicate(
    "created_at exists",
    settings.created_at !== null && settings.created_at !== undefined,
  );
  TestValidator.predicate(
    "updated_at exists",
    settings.updated_at !== null && settings.updated_at !== undefined,
  );
}

