/**
 * Test employee listing with pagination functionality.
 * Verifies that authenticated members can retrieve paginated employee lists
 * with proper structure and pagination metadata.
 */
export async function test_api_employee_list_with_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as member
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 2. List employees with pagination
  const response = await api.functional.hrmPlatform.member.employees.index(
    memberConnection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IHrmPlatformEmployee.IRequest,
    },
  );
  typia.assert(response);
  // 3. Validate pagination metadata
  TestValidator.equals("current page is 1", response.pagination.current, 1);
  TestValidator.equals("limit is 10", response.pagination.limit, 10);
  TestValidator.predicate(
    "records count is non-negative",
    response.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    response.pagination.pages >= 0,
  );
  // 4. Validate pagination calculation
  const expectedPages =
    response.pagination.records === 0
      ? 0
      : Math.ceil(response.pagination.records / response.pagination.limit);
  TestValidator.equals(
    "pages calculation is correct",
    response.pagination.pages,
    expectedPages,
  );
  // 5. Validate data array length respects limit
  TestValidator.predicate(
    "data length does not exceed limit",
    response.data.length <= response.pagination.limit,
  );
  // 6. Test with different pagination parameters
  const responsePage2 = await api.functional.hrmPlatform.member.employees.index(
    memberConnection,
    {
      body: {
        page: 2,
        limit: 5,
      } satisfies IHrmPlatformEmployee.IRequest,
    },
  );
  typia.assert(responsePage2);
  TestValidator.equals(
    "current page is 2",
    responsePage2.pagination.current,
    2,
  );
  TestValidator.equals("limit is 5", responsePage2.pagination.limit, 5);
  // 7. Test with filter parameters
  const responseWithFilter =
    await api.functional.hrmPlatform.member.employees.index(memberConnection, {
      body: {
        page: 1,
        limit: 10,
        employment_type: "full-time",
        status: "active",
      } satisfies IHrmPlatformEmployee.IRequest,
    });
  typia.assert(responseWithFilter);
  TestValidator.equals(
    "current page is 1",
    responseWithFilter.pagination.current,
    1,
  );
  // 8. Verify filtered results match criteria (business logic)
  for (const employee of responseWithFilter.data) {
    TestValidator.equals(
      "employment_type matches filter",
      employee.employment_type,
      "full-time",
    );
    TestValidator.equals("status matches filter", employee.status, "active");
  }
  // 9. Test with search parameter
  const searchQuery = RandomGenerator.alphabets(3);
  const responseWithSearch =
    await api.functional.hrmPlatform.member.employees.index(memberConnection, {
      body: {
        page: 1,
        limit: 10,
        search: searchQuery,
      } satisfies IHrmPlatformEmployee.IRequest,
    });
  typia.assert(responseWithSearch);
  TestValidator.equals(
    "search returns valid response",
    responseWithSearch.pagination.current,
    1,
  );
  // 10. Test with department filter (null)
  const responseWithNullDepartment =
    await api.functional.hrmPlatform.member.employees.index(memberConnection, {
      body: {
        page: 1,
        limit: 10,
        department_id: null,
      } satisfies IHrmPlatformEmployee.IRequest,
    });
  typia.assert(responseWithNullDepartment);
  TestValidator.equals(
    "null department filter works",
    responseWithNullDepartment.pagination.current,
    1,
  );
}

