  TestValidator.equals(
    "role name should remain unchanged after failed conflict updates",
    updatedRole.name,
    originalRoleName,
  );
  // 8. Validate that role ID is unchanged
  TestValidator.equals(
    "role id should remain unchanged",
    updatedRole.id,
    customRole.id,
  );
}

