      `employee ${index} member has email`,
      () => membership.employee.member.email !== undefined,
    );
    // 10. Verify employee has role information
    TestValidator.predicate(
      `employee ${index} has role`,
      () => membership.employee.role !== undefined,
    );
  });
}

