/**
 * Test the primary success path for soft deleting a task.
 * 1. Authenticate as a member
 * 2. Create a project
 * 3. Create a task within the project
 * 4. Verify task is active (deleted_at is null)
 * 5. Soft delete the task
 * 6. Verify the delete operation completes successfully
 *
 * Note: The erase endpoint returns void, so we cannot verify the deleted_at
 * timestamp directly. The backend should set deleted_at and preserve the
 * task record with all other fields intact.
 */
export async function test_api_task_soft_delete_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as member
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {});
  // 2. Create a project
  const project = await generate_random_hrm_platform_member_projects_create(
    memberConnection,
    {},
  );
  typia.assert(project);
  // 3. Create a task within the project
  const task = await generate_random_hrm_platform_member_projects_tasks_create(
    memberConnection,
    {
      params: { projectId: project.id },
      body: {},
    },
  );
  typia.assert(task);
  // 4. Verify task is initially active (not deleted)
  TestValidator.equals("task deleted_at is null", task.deleted_at, null);
  TestValidator.predicate("task has valid title", task.title.length > 0);
  TestValidator.predicate(
    "task belongs to project",
    task.project.id === project.id,
  );
  // 5. Soft delete the task
  await api.functional.hrmPlatform.member.tasks.erase(memberConnection, {
    taskId: task.id,
  });
  // 6. Verify the delete operation completed without error
  // The backend should have:
  // - Set deleted_at to current timestamp
  // - Preserved all other task fields
  // - Created activity log entry
  // - Preserved task history entries
  TestValidator.predicate("soft delete operation completed successfully", true);
}

