      body: {
        title: "Test Task for Snapshot",
        description: "This task will be snapshotted for testing",
        status: "open",
        priority: "high",
        due_date: new Date(Date.now() + 86400000 * 7).toISOString(),
        estimated_hours: 8,
      },
    },
