/**
 * Test creating a task snapshot for a task that has an employee assigned.
 * This scenario validates that the snapshot correctly captures the employee
 * assignment relationship and includes the employee reference in the
 * denormalized snapshot data.
 */
export async function test_api_task_snapshot_with_employee_assignment(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as a member user
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {});
  // 2. Create a project as prerequisite for task creation
  const project = await generate_random_hrm_platform_member_projects_create(
    memberConnection,
    {},
  );
  typia.assert(project);
  // 3. Create a task within the project with employee assignment
  const task = await generate_random_hrm_platform_member_projects_tasks_create(
    memberConnection,
    {
      params: {
        projectId: project.id,
      },
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        status: "open",
        priority: "high",
        due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        estimated_hours: 16,
      } satisfies IHrmPlatformTask.ICreate,
    },
  );
  typia.assert(task);
  // 4. Create a task snapshot for the task
  const snapshot =
    await generate_random_hrm_platform_member_task_snapshots_create(
      memberConnection,
      {
        body: {
          hrm_platform_task_id: task.id,
        },
      },
    );
  typia.assert(snapshot);
  // 5. Verify the snapshot correctly captures task state
  TestValidator.equals(
    "snapshot title matches task title",
    snapshot.title,
    task.title,
  );
  TestValidator.equals(
    "snapshot description matches task description",
    snapshot.description,
    task.description,
  );
  TestValidator.equals(
    "snapshot status matches task status",
    snapshot.status,
    task.status,
  );
  TestValidator.equals(
    "snapshot priority matches task priority",
    snapshot.priority,
    task.priority,
  );
  TestValidator.equals(
    "snapshot due_date matches task due_date",
    snapshot.due_date,
    task.due_date,
  );
  TestValidator.equals(
    "snapshot estimated_hours matches task estimated_hours",
    snapshot.estimated_hours,
    task.estimated_hours,
  );
  // 6. Verify snapshot temporal fields
  TestValidator.equals(
    "snapshot task_created_at matches task created_at",
    snapshot.task_created_at,
    task.created_at,
  );
  TestValidator.equals(
    "snapshot updated_at matches task updated_at",
    snapshot.updated_at,
    task.updated_at,
  );
  TestValidator.equals(
    "snapshot deleted_at matches task deleted_at",
    snapshot.deleted_at,
    task.deleted_at,
  );
  TestValidator.predicate(
    "snapshot has snapshot_created_at timestamp",
    snapshot.snapshot_created_at !== undefined,
  );
  // 7. Verify snapshot project reference
  TestValidator.equals(
    "snapshot project id matches task project",
    snapshot.project.id,
    task.project.id,
  );
  TestValidator.equals(
    "snapshot project name matches task project",
    snapshot.project.name,
    task.project.name,
  );
  // 8. Verify employee assignment is correctly captured in snapshot
  // If task has assigned employee, snapshot should have it too
  if (task.assignedEmployee !== null) {
    TestValidator.predicate(
      "snapshot has employee when task has assigned employee",
      snapshot.employee !== null,
    );
    if (snapshot.employee !== null) {
      TestValidator.equals(
        "snapshot employee id matches task assigned employee",
        snapshot.employee.id,
        task.assignedEmployee.id,
      );
      TestValidator.equals(
        "snapshot employee employment_type matches",
        snapshot.employee.employment_type,
        task.assignedEmployee.employment_type,
      );
      TestValidator.equals(
        "snapshot employee status matches",
        snapshot.employee.status,
        task.assignedEmployee.status,
      );
      TestValidator.equals(
        "snapshot employee member id matches",
        snapshot.employee.member.id,
        task.assignedEmployee.member.id,
      );
      TestValidator.equals(
        "snapshot employee role id matches",
        snapshot.employee.role.id,
        task.assignedEmployee.role.id,
      );
    }
  } else {
    TestValidator.equals(
      "snapshot employee is null when task has no assigned employee",
      snapshot.employee,
      null,
    );
  }
}

