export async function test_api_task_history_access_control(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Test task history access control for admin users.
   * Validates that task history entries are properly filtered based on
   * admin permissions and task visibility across multiple projects.
   */
  // 1. Create admin connection and authenticate
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IHrmPlatformAdmin.ILogin,
  });
  // 2. Create first project (accessible project)
  const accessibleProject =
    await generate_random_hrm_platform_member_projects_create(adminConnection, {
      body: {
        name: "Accessible Project - " + RandomGenerator.alphabets(8),
        description: "Project that admin has access to",
        status: "active",
        color_code: "#3498db",
        budget_hours: 100,
      },
    });
  typia.assert(accessibleProject);
  // 3. Create second project (for testing access boundaries)
  const boundaryProject =
    await generate_random_hrm_platform_member_projects_create(adminConnection, {
      body: {
        name: "Boundary Project - " + RandomGenerator.alphabets(8),
        description: "Project for testing access boundaries",
        status: "active",
        color_code: "#e74c3c",
        budget_hours: 200,
      },
    });
  typia.assert(boundaryProject);
  // 4. Create task in accessible project
  const accessibleTask =
    await generate_random_hrm_platform_admin_projects_tasks_create(
      adminConnection,
      {
        params: { projectId: accessibleProject.id },
        body: {
          title: "Accessible Task - " + RandomGenerator.name(),
          description: "Task in accessible project",
          status: "open",
          priority: "high",
          due_date: new Date(
            Date.now() + 7 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          estimated_hours: 10,
        },
      },
    );
  typia.assert(accessibleTask);
  // 5. Update task status to generate history in accessible project
  const updatedAccessibleTask =
    await api.functional.hrmPlatform.admin.tasks.update(adminConnection, {
      taskId: accessibleTask.id,
      body: {
        status: "in-progress",
      } satisfies IHrmPlatformTask.IUpdate,
    });
  typia.assert(updatedAccessibleTask);
  // 6. Create task in boundary project
  const boundaryTask =
    await generate_random_hrm_platform_admin_projects_tasks_create(
      adminConnection,
      {
        params: { projectId: boundaryProject.id },
        body: {
          title: "Boundary Task - " + RandomGenerator.name(),
          description: "Task in boundary project",
          status: "open",
          priority: "medium",
          due_date: new Date(
            Date.now() + 14 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          estimated_hours: 20,
        },
      },
    );
  typia.assert(boundaryTask);
  // 7. Update boundary task status to generate history
  const updatedBoundaryTask =
    await api.functional.hrmPlatform.admin.tasks.update(adminConnection, {
      taskId: boundaryTask.id,
      body: {
        status: "completed",
      } satisfies IHrmPlatformTask.IUpdate,
    });
  typia.assert(updatedBoundaryTask);
  // 8. Query task history without filters to get all entries
  const allHistory =
    await api.functional.hrmPlatform.admin.task_histories.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IHrmPlatformTaskHistory.IRequest,
      },
    );
  typia.assert(allHistory);
  // 9. Validate that history entries exist
  TestValidator.predicate("history entries exist", allHistory.data.length > 0);
  // 10. Validate that history entries contain expected status transitions
  const accessibleHistory = allHistory.data.filter(
    (entry) => entry.task.id === accessibleTask.id,
  );
  TestValidator.equals(
    "accessible task has history entries",
    accessibleHistory.length,
    1,
  );
  // 11. Validate history entry structure for accessible task
  if (accessibleHistory.length > 0) {
    const historyEntry = accessibleHistory[0];
    TestValidator.equals(
      "history old_status is correct",
      historyEntry.old_status,
      "open",
    );
    TestValidator.equals(
      "history new_status is correct",
      historyEntry.new_status,
      "in-progress",
    );
    TestValidator.equals(
      "history task_id matches",
      historyEntry.task.id,
      accessibleTask.id,
    );
    TestValidator.equals(
      "history task_title matches",
      historyEntry.task.title,
      accessibleTask.title,
    );
  }
  // 12. Validate boundary task history
  const boundaryHistory = allHistory.data.filter(
    (entry) => entry.task.id === boundaryTask.id,
  );
  TestValidator.equals(
    "boundary task has history entries",
    boundaryHistory.length,
    1,
  );
  // 13. Validate history entry structure for boundary task
  if (boundaryHistory.length > 0) {
    const historyEntry = boundaryHistory[0];
    TestValidator.equals(
      "boundary history old_status is correct",
      historyEntry.old_status,
      "open",
    );
    TestValidator.equals(
      "boundary history new_status is correct",
      historyEntry.new_status,
      "completed",
    );
    TestValidator.equals(
      "boundary history task_id matches",
      historyEntry.task.id,
      boundaryTask.id,
    );
  }
  // 14. Test filtering by taskId
  const filteredByTaskId =
    await api.functional.hrmPlatform.admin.task_histories.index(
      adminConnection,
      {
        body: {
          taskId: accessibleTask.id,
