  typia.assert(activeTimer2);
  // Stopped timer for project1
  const stoppedTimer1 = await generate_random_hrm_platform_admin_timers_create(
    adminConnection,
    {
      body: {
        projectId: project1.id,
        description: "Meeting with team",
      },
