    projectFilterResult.pagination.records,
    projectFilterResult.data.length,
  );
  // 9. Test search filter on description
  const searchResult = await api.functional.hrmPlatform.admin.timers.index(
    adminConnection,
    {
      body: {
        search: "feature",
        page: 1,
        limit: 20,
