/**
 * Test deletion of a running timer session (discard operation).
 * 1. Authenticate as a member
 * 2. Create a running timer session
 * 3. Delete the running timer (discard without creating timelog)
 * 4. Verify member can start a new timer after discarding
 */
export async function test_api_timer_delete_running_timer_discard(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as member
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IHrmPlatformMember.IJoin,
  });
  // 2. Create a running timer session
  const timer = await generate_random_hrm_platform_member_timers_create(
    memberConnection,
    {},
  );
  typia.assert(timer);
  // Store timer state before deletion
  const originalTimerId = timer.id;
  // 3. Delete the running timer (discard operation)
  // This should soft-delete the timer without creating a timelog
  await api.functional.hrmPlatform.member.timers.erase(memberConnection, {
    timerId: timer.id,
  });
  // 4. Verify the timer was soft-deleted by attempting to delete it again
  // Should fail with 410 Gone or similar error
  await TestValidator.error(
    "deleted timer should not be accessible",
    async () => {
      await api.functional.hrmPlatform.member.timers.erase(memberConnection, {
        timerId: originalTimerId,
      });
    },
  );
  // 5. Verify member can start a new timer after discarding the previous one
  // This confirms the discard operation properly released the timer slot
  const newTimer = await generate_random_hrm_platform_member_timers_create(
    memberConnection,
    {},
  );
  typia.assert(newTimer);
  // Verify the new timer is different from the deleted one
  TestValidator.notEquals(
    "new timer has different ID",
    newTimer.id,
    originalTimerId,
  );
}

