    },
  });
  // 2. Calculate a past Monday date for the timesheet week
  const now = new Date();
  const pastMonday = new Date(now);
  pastMonday.setDate(now.getDate() - 7 - now.getDay() + 1);
  pastMonday.setHours(0, 0, 0, 0);
  const weekStartDate = pastMonday.toISOString();
