export async function test_api_timesheet_update_week_overlap_prevention(
  connection: api.IConnection,
): Promise<void> {
  /**
   * Test the validation rule that prevents updating a timesheet's week_start_date
   * to overlap with existing submitted or approved timesheets. This ensures data
   * integrity by preventing duplicate time records for the same employee in the same week.
   */
  // 1. Authenticate as member
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 2. Generate two Monday dates for different weeks (7 days apart)
  const now = new Date();
  const monday1 = new Date(now);
  monday1.setDate(now.getDate() - now.getDay() + 1); // This week's Monday
  monday1.setHours(0, 0, 0, 0);
  const monday2 = new Date(monday1);
  monday2.setDate(monday1.getDate() + 7); // Next week's Monday
  monday2.setHours(0, 0, 0, 0);
  const week1Start = monday1.toISOString();
  const week2Start = monday2.toISOString();
  // 3. Create first draft timesheet for Week 1
  const timesheet1 =
    await generate_random_hrm_platform_member_timesheets_create(
      memberConnection,
      {
        body: {
          week_start_date: week1Start,
        },
      },
    );
  typia.assert(timesheet1);
  // 4. Create second draft timesheet for Week 2
  const timesheet2 =
    await generate_random_hrm_platform_member_timesheets_create(
      memberConnection,
      {
        body: {
          week_start_date: week2Start,
        },
      },
    );
  typia.assert(timesheet2);
  // 5. Verify initial state - timesheets have different week_start_dates
  TestValidator.notEquals(
    "initial week_start_dates differ",
    timesheet1.week_start_date,
    timesheet2.week_start_date,
  );
  // 6. Attempt to update timesheet1's week_start_date to Week 2 (overlap with timesheet2)
  // This should fail because timesheet2 already exists for Week 2
  await TestValidator.error("week overlap prevention", async () => {
    await api.functional.hrmPlatform.member.timesheets.update(
      memberConnection,
      {
        timesheetId: timesheet1.id,
        body: {
          week_start_date: week2Start,
        } satisfies IHrmPlatformTimesheet.IUpdate,
      },
    );
  });
  // 7. Verify that timesheet1 can still be updated to a non-overlapping week
  const monday3 = new Date(monday2);
  monday3.setDate(monday2.getDate() + 7); // Week after Week 2
  monday3.setHours(0, 0, 0, 0);
  const week3Start = monday3.toISOString();
  const updatedTimesheet1 =
    await api.functional.hrmPlatform.member.timesheets.update(
      memberConnection,
      {
        timesheetId: timesheet1.id,
        body: {
          week_start_date: week3Start,
        } satisfies IHrmPlatformTimesheet.IUpdate,
      },
    );
  typia.assert(updatedTimesheet1);
  TestValidator.equals(
    "timesheet1 updated to non-overlapping week",
    updatedTimesheet1.week_start_date,
    week3Start,
  );
  // 8. Verify timesheet2 remains unchanged
  TestValidator.equals(
    "timesheet2 week_start_date unchanged",
    timesheet2.week_start_date,
    week2Start,
  );
}

