    deleted_at: null,
    project: {
      memberships: {
        some: {
          hrm_platform_employee_id: employee.id,
          deleted_at: null,
        },
      },
    },
  };
  if (props.body.status !== undefined) {
    whereInput.status = props.body.status;
  }
  if (props.body.priority !== undefined) {
