import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IHrmPlatformAdmin } from "../../../../api/structures/IHrmPlatformAdmin";
import { postHrmPlatformAuthAdminJoin } from "../../../../providers/postHrmPlatformAuthAdminJoin";
import { postHrmPlatformAuthAdminLogin } from "../../../../providers/postHrmPlatformAuthAdminLogin";
import { postHrmPlatformAuthAdminRefresh } from "../../../../providers/postHrmPlatformAuthAdminRefresh";

@Controller("/hrmPlatform/auth/admin")
export class HrmplatformAuthAdminController {
  /**
   * This API operation creates a new administrator account for the HRM Platform. Administrators are system users with elevated privileges who can manage platform-wide settings, view all organizations, and handle support requests.
   *
   * The operation accepts an email address and password in the request body. The email must be unique across all administrator accounts in the system. The password is securely hashed using the BCrypt algorithm before storage in the hrm_platform_admins table. Upon successful creation, the system generates JWT access and refresh tokens, allowing the new administrator to immediately authenticate and access the platform.
   *
   * The hrm_platform_admins table stores the administrator's core authentication data: unique email identifier, BCrypt-hashed password, creation timestamp (created_at), last update timestamp (updated_at), and optional soft-delete timestamp (deleted_at). The operation also creates an initial session record in hrm_platform_admin_sessions, tracking the login IP address, href URL, and referrer for security auditing purposes.
   *
   * This endpoint is publicly accessible (no authentication required) as it is the registration mechanism for new administrators. After successful registration, administrators can use the login endpoint to authenticate with their credentials or use the refresh endpoint to renew their tokens.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator registration information including email and password
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification This operation creates a new administrator account with email and password credentials. The service layer must:
   *
   * 1. Validate that the email is not already registered (check hrm_platform_admins.email uniqueness)
   * 2. Hash the password using BCrypt algorithm and store in password_hash field
   * 3. Create a new record in hrm_platform_admins table with generated UUID, email, password_hash, created_at, updated_at timestamps
   * 4. Generate JWT access and refresh tokens for immediate authentication
   * 5. Create an initial session record in hrm_platform_admin_sessions with IP, href, referrer from request context
   * 6. Return the authorized response containing tokens and admin information
   *
   * Error handling:
   * - Return 400 Bad Request if email format is invalid
   * - Return 409 Conflict if email already exists
   * - Return 500 Internal Server Error for database or token generation failures
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IHrmPlatformAdmin.IJoin,
  ): Promise<IHrmPlatformAdmin.IAuthorized> {
    try {
      return await postHrmPlatformAuthAdminJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * This API operation authenticates an administrator using email and password credentials. Administrators are system users with elevated privileges who can manage platform-wide settings, view all organizations, and handle support requests.
   *
   * The operation accepts an email address and password in the request body. The system validates these credentials against the hrm_platform_admins table, which stores unique email addresses and BCrypt-hashed passwords. Upon successful authentication, the system generates new JWT access and refresh tokens and creates a session record in hrm_platform_admin_sessions.
   *
   * The session record tracks important metadata for security auditing: the IP address from which the login was initiated, the href URL where the administrator accessed the login page, and the referrer URL that directed them to the platform. This information is crucial for detecting suspicious login patterns and maintaining an audit trail of administrator access.
   *
   * This endpoint is publicly accessible (no authentication required) as it is the authentication mechanism for administrators. After successful login, administrators can access protected resources using the JWT tokens and use the refresh endpoint to renew their tokens when they expire.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator login credentials including email and password
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification This operation authenticates an administrator using email and password credentials. The service layer must:
   *
   * 1. Find the administrator record in hrm_platform_admins by email address
   * 2. Verify the administrator is not soft-deleted (deleted_at is null)
   * 3. Compare the provided password with the stored password_hash using BCrypt verification
   * 4. If credentials are valid, generate new JWT access and refresh tokens
   * 5. Create a new session record in hrm_platform_admin_sessions with current IP, href, referrer, and created_at timestamp
   * 6. Return the authorized response containing tokens and administrator information
   *
   * Error handling:
   * - Return 401 Unauthorized if email not found or password incorrect
   * - Return 403 Forbidden if account is soft-deleted
   * - Return 500 Internal Server Error for database or token generation failures
   *
   * Security considerations:
   * - Implement rate limiting to prevent brute force attacks
   * - Log failed login attempts in hrm_platform_activity_logs for audit trail
   * - Use constant-time comparison for password verification to prevent timing attacks
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IHrmPlatformAdmin.ILogin,
  ): Promise<IHrmPlatformAdmin.IAuthorized> {
    try {
      return await postHrmPlatformAuthAdminLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * This API operation refreshes an administrator's authentication tokens using a valid refresh token. This allows administrators to maintain their authenticated session without re-entering credentials.
   *
   * The operation accepts a refresh token in the request body. The system validates this token by verifying its cryptographic signature, checking its expiration time, and extracting the administrator identity from its claims. Upon successful validation, the system generates new JWT access and refresh tokens with updated expiration timestamps.
   *
   * The refresh mechanism is essential for maintaining secure, long-lived sessions. Access tokens typically have short expiration times (e.g., 15 minutes) for security, while refresh tokens have longer lifetimes (e.g., 7 days). When an access token expires, the administrator uses this endpoint to obtain a new access token without re-authenticating.
