   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @AdminAuth()
    admin: AdminPayload,
    @TypedBody()
    body: IHrmPlatformDepartment.ICreate,
  ): Promise<IHrmPlatformDepartment> {
